<# Generates original Sentinel Core runtime art without third-party inputs. #>
[CmdletBinding()]
param([string]$OutputRoot = (Join-Path $PSScriptRoot '..\assets\generated\chapter1\runtime\environment\sentinel_core'))
$ErrorActionPreference='Stop'; Add-Type -AssemblyName System.Drawing
function C([int]$w=64,[int]$h=64,[bool]$o=$false){$b=[Drawing.Bitmap]::new($w,$h,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[Drawing.Graphics]::FromImage($b);$g.SmoothingMode='AntiAlias';$g.Clear($(if($o){[Drawing.Color]::FromArgb(255,13,20,27)}else{[Drawing.Color]::Transparent}));@($b,$g)}
function B([string]$x,[int]$a=255){$c=[Drawing.ColorTranslator]::FromHtml($x);[Drawing.SolidBrush]::new([Drawing.Color]::FromArgb($a,$c.R,$c.G,$c.B))}
function P([string]$x,[single]$w=1,[int]$a=255){$c=[Drawing.ColorTranslator]::FromHtml($x);[Drawing.Pen]::new([Drawing.Color]::FromArgb($a,$c.R,$c.G,$c.B),$w)}
function S($c,[string]$r){$p=Join-Path $OutputRoot $r;New-Item -ItemType Directory -Force -Path (Split-Path $p)|Out-Null;$c[1].Dispose();$c[0].Save($p,[Drawing.Imaging.ImageFormat]::Png);$c[0].Dispose()}
for($i=0;$i -lt 8;$i++){$c=C 64 64 $true;$g=$c[1];$b=B @('#17232e','#22313b','#123b47','#4b202c','#26313d','#1c2633','#15313a','#315865')[$i];$g.FillRectangle($b,3,3,58,58);$b.Dispose();$p=P '#7eeeff' 1 120;$g.DrawEllipse($p,8+$i%3,8+$i%3,48-$i%3*2,48-$i%3*2);$g.DrawLine($p,32,4,32,60);$g.DrawLine($p,4,32,60,32);$p.Dispose();if($i -eq 2 -or $i -eq 7){$b=B '#82ffff' 120;$g.FillEllipse($b,20,20,24,24);$b.Dispose()}if($i -eq 3){$b=B '#ef4668' 120;$g.FillRectangle($b,27,4,10,56);$b.Dispose()}S $c ("floor/floor_{0:d2}.png" -f $i)}
$e=@('north','east','south','west','corner_nw','corner_ne','corner_se','corner_sw');for($i=0;$i -lt 8;$i++){$c=C;$g=$c[1];$p=P '#90f8ff' 3 220;switch($i){0{$g.DrawLine($p,0,5,64,5)}1{$g.DrawLine($p,59,0,59,64)}2{$g.DrawLine($p,0,59,64,59)}3{$g.DrawLine($p,5,0,5,64)}4{$g.DrawArc($p,4,4,56,56,180,90)}5{$g.DrawArc($p,4,4,56,56,270,90)}6{$g.DrawArc($p,4,4,56,56,0,90)}7{$g.DrawArc($p,4,4,56,56,90,90)}}$p.Dispose();S $c ("edge/edge_{0}.png" -f $e[$i])}
for($i=0;$i -lt 6;$i++){$c=C;$g=$c[1];$dark=B '#17232e';$light=B @('#8bfbff','#4ee1e1','#d7f5ff','#e95e78','#72a8bf','#d6e5ef')[$i];$g.FillEllipse($dark,8,8,48,48);$g.FillEllipse($light,16+$i%2*4,14,32,38);$dark.Dispose();$light.Dispose();S $c ("prop/prop_{0:d2}.png" -f $i)}
for($i=0;$i -lt 3;$i++){$c=C;$g=$c[1];$p=P @('#ef4d6e','#8cffff','#c6e6ff')[$i] 3 180;if($i -eq 0){$g.DrawEllipse($p,8,8,48,48)}elseif($i -eq 1){$g.DrawLine($p,8,8,56,56);$g.DrawLine($p,56,8,8,56)}else{$g.DrawRectangle($p,12,12,40,40)}$p.Dispose();S $c ("decal/decal_{0:d2}.png" -f $i)}
$c=C 192 128;$g=$c[1];$o=B '#172b38';$gl=B '#9affff';$g.FillEllipse($o,18,4,156,120);$g.FillEllipse($gl,52,28,88,72);$o.Dispose();$gl.Dispose();S $c 'landmark/sentinel_aperture_192x128.png'
$c=C 128 128;$g=$c[1];$p=P '#a0f8ff' 8 230;$g.DrawLine($p,28,116,45,16);$g.DrawLine($p,100,116,83,16);$p.Dispose();$b=B '#f15b77';$g.FillEllipse($b,37,8,18,18);$g.FillEllipse($b,73,8,18,18);$b.Dispose();S $c 'landmark/phase_pylons_128.png'
